from __future__ import annotations

import hashlib
import hmac
import json
import re
import uuid
from datetime import datetime
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data


MAX_REGISTRY_ITEMS = 500
ALLOWED_VISIBILITY = {"tenant", "group", "private"}
FORBIDDEN_INSTRUCTION_PATTERNS = (
    r"(?i)\b(?:python|powershell|bash|shell|cmd\.exe)\b.{0,40}\b(?:run|execute|실행)\b",
    r"(?i)\b(?:eval|exec|subprocess|os\.system|tool\s*/?\s*add)\b",
    r"(?i)\b(?:secret|password|token|credential|비밀|암호)\b.{0,40}\b(?:read|send|print|조회|전송|출력)\b",
    r"(?i)\b(?:ignore|override|bypass|무시|우회)\b.{0,50}\b(?:policy|system|safety|acl|approval|정책|승인)\b",
)
SECRET_VALUE_PATTERNS = (
    re.compile(r"(?i)\b(?:api[_-]?key|password|passwd|secret|access[_-]?token|client[_-]?secret|authorization|cookie|session)\s*[:=]\s*[\"']?[^\s,;]{8,}"),
    re.compile(r"(?i)\b(?:bearer|basic)\s+\S{8,}"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\b[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"[a-zA-Z][a-zA-Z0-9+.-]*://[^/@\s]+:[^/@\s]+@"),
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
)
REGISTRY_ENTRY_KEYS = {
    "tenant_id", "skill_id", "name", "version", "prompt_sha256", "trigger_rules", "near_miss_rules",
    "prompt_text", "forbidden_actions", "status", "acl", "approved_by", "approved_at", "match_reason",
    "target_stage",
}
ACL_KEYS = {"visibility", "groups", "subjects"}


def _payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list)):
        return data
    if isinstance(value, str) and value.strip():
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return {}
    return {}


def _items(value: Any, *keys: str) -> list[dict[str, Any]]:
    payload = _payload(value)
    if isinstance(payload, list):
        raw = payload
    elif isinstance(payload, dict):
        raw = []
        for key in keys:
            if isinstance(payload.get(key), list):
                raw = payload[key]
                break
    else:
        raw = []
    return [item for item in raw[:MAX_REGISTRY_ITEMS] if isinstance(item, dict)]


def _approved_registry_items(value: Any) -> tuple[list[dict[str, Any]], str]:
    """Accept an explicitly supplied empty registry, but never infer one.

    An empty `skills` list is the valid representation when a team has no
    approved Skills.  In contrast, an omitted registry, a failed upstream
    envelope, or a non-list `skills` value must remain fail-closed: treating
    those as an empty registry would discard an upstream failure.
    """
    payload = _payload(value)
    if isinstance(payload, list):
        raw = payload
    elif isinstance(payload, dict):
        if "ok" in payload and payload.get("ok") is not True:
            return [], "SKILL_REGISTRY_UPSTREAM_FAILED"
        if "skills" not in payload:
            return [], "SKILL_REGISTRY_EMPTY"
        raw = payload.get("skills")
    else:
        return [], "SKILL_REGISTRY_EMPTY"
    if not isinstance(raw, list):
        return [], "SKILL_REGISTRY_CONTRACT_INVALID"
    if len(raw) > MAX_REGISTRY_ITEMS or any(not isinstance(item, dict) for item in raw):
        return [], "SKILL_REGISTRY_CONTRACT_INVALID"
    return list(raw), ""


def _strings(value: Any, maximum: int = 100) -> list[str]:
    if isinstance(value, str):
        source = re.split(r"[,;\n]", value)
    elif isinstance(value, (list, tuple, set)):
        source = list(value)
    else:
        source = []
    result: list[str] = []
    for item in source[:maximum]:
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


def _canonical_hash(text: str) -> str:
    normalized = text.replace("\r\n", "\n").replace("\r", "\n")
    return "sha256:" + hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def _scope_hash(scope: dict[str, Any]) -> str:
    keys = [
        "schema_version",
        "tenant_id",
        "catalog_snapshot_id",
        "work_definition_id",
        "work_definition_revision",
        "approved_hash",
        "work_definition",
        "acl_context",
        "design_prompt",
    ]
    # Newer F20 scopes bind a retrieval-only original-request seed by hash.
    # Keep older direct-test scopes valid while preserving the new lock when it
    # is present.
    if "search_seed_sha256" in scope:
        keys.append("search_seed_sha256")
    material = json.dumps({key: scope.get(key) for key in keys}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def _hash_matches(expected: Any, text: str) -> bool:
    supplied = str(expected or "").strip().lower()
    actual = _canonical_hash(text).lower()
    return supplied in {actual, actual.removeprefix("sha256:")}


def _safe_trace_identity(value: Any, *, skill_id: bool = False) -> str:
    if type(value) is not str or not value or len(value) > 128:
        return "[INVALID]"
    if skill_id and re.fullmatch(r"[a-z][a-z0-9_-]{1,127}", value) is None:
        return "[INVALID]"
    if any(pattern.search(value) for pattern in SECRET_VALUE_PATTERNS):
        return "[INVALID]"
    return value


def _registry_contract_error(entry: dict[str, Any]) -> str:
    if set(entry) - REGISTRY_ENTRY_KEYS:
        return "SKILL_REGISTRY_CONTRACT_INVALID"
    if any(not isinstance(entry.get(key), str) for key in ("tenant_id", "skill_id", "version", "prompt_sha256")):
        return "INVALID_REGISTRY_IDENTITY"
    tenant_id = str(entry.get("tenant_id") or "")
    skill_id = str(entry.get("skill_id") or "")
    name = entry.get("name")
    version = str(entry.get("version") or "")
    prompt_hash = str(entry.get("prompt_sha256") or "")
    prompt_text = entry.get("prompt_text")
    if not tenant_id or len(tenant_id) > 128 or not re.fullmatch(r"[a-z][a-z0-9_-]{1,127}", skill_id):
        return "INVALID_REGISTRY_IDENTITY"
    if not version or len(version) > 128 or not re.fullmatch(r"sha256:[0-9a-f]{64}", prompt_hash):
        return "INVALID_REGISTRY_IDENTITY"
    if not isinstance(name, str) or not name.strip() or len(name) > 256:
        return "INVALID_REGISTRY_IDENTITY"
    if not isinstance(prompt_text, str) or not prompt_text or len(prompt_text) > 50_000:
        return "INVALID_REGISTRY_PROMPT"
    approved_by = entry.get("approved_by")
    approved_at = entry.get("approved_at")
    if not isinstance(approved_by, str) or not approved_by.strip() or len(approved_by) > 256:
        return "SKILL_APPROVAL_EVIDENCE_INVALID"
    if not isinstance(approved_at, str) or len(approved_at) > 64:
        return "SKILL_APPROVAL_EVIDENCE_INVALID"
    try:
        parsed_approval_time = datetime.fromisoformat(approved_at.replace("Z", "+00:00"))
    except ValueError:
        return "SKILL_APPROVAL_EVIDENCE_INVALID"
    if parsed_approval_time.tzinfo is None:
        return "SKILL_APPROVAL_EVIDENCE_INVALID"
    trigger_rules = entry.get("trigger_rules")
    near_miss_rules = entry.get("near_miss_rules")
    if not isinstance(trigger_rules, list) or not 1 <= len(trigger_rules) <= 100:
        return "SKILL_RULE_CONTRACT_INVALID"
    if not isinstance(near_miss_rules, list) or len(near_miss_rules) > 100:
        return "SKILL_RULE_CONTRACT_INVALID"
    if any(not _valid_rule(rule) for rule in [*trigger_rules, *near_miss_rules]):
        return "SKILL_RULE_CONTRACT_INVALID"
    if type(entry.get("status")) is not str or entry.get("status") not in {"active", "inactive", "revoked"}:
        return "INVALID_REGISTRY_STATUS"
    forbidden_actions = entry.get("forbidden_actions", [])
    if (
        not isinstance(forbidden_actions, list)
        or len(forbidden_actions) > 100
        or any(not isinstance(item, str) or len(item) > 128 for item in forbidden_actions)
    ):
        return "SKILL_REGISTRY_CONTRACT_INVALID"
    match_reason = entry.get("match_reason")
    target_stage = entry.get("target_stage")
    if match_reason is not None and (not isinstance(match_reason, str) or len(match_reason) > 500):
        return "SKILL_REGISTRY_CONTRACT_INVALID"
    if target_stage is not None and (not isinstance(target_stage, str) or len(target_stage) > 100):
        return "SKILL_REGISTRY_CONTRACT_INVALID"
    acl = entry.get("acl")
    if not isinstance(acl, dict) or str(acl.get("visibility") or "") not in ALLOWED_VISIBILITY:
        return "SKILL_ACL_INVALID"
    if set(acl) - ACL_KEYS:
        return "SKILL_ACL_INVALID"
    if "groups" not in acl:
        return "SKILL_ACL_INVALID"
    groups = acl.get("groups")
    subjects = acl.get("subjects", [])
    if not isinstance(groups, list) or len(groups) > 200 or any(not isinstance(item, str) or not item.strip() or len(item) > 128 for item in groups):
        return "SKILL_ACL_INVALID"
    if not isinstance(subjects, list) or len(subjects) > 200 or any(not isinstance(item, str) or not item.strip() or len(item) > 256 for item in subjects):
        return "SKILL_ACL_INVALID"
    visibility = str(acl["visibility"])
    if visibility == "group" and not groups:
        return "SKILL_ACL_INVALID"
    if visibility == "private" and not subjects:
        return "SKILL_ACL_INVALID"
    return ""


def _valid_rule(rule: Any) -> bool:
    if isinstance(rule, str):
        return bool(rule.strip()) and len(rule) <= 1000
    if not isinstance(rule, dict) or set(rule) - {"kind", "value", "values", "terms"}:
        return False
    kind = str(rule.get("kind") or "contains").lower()
    if kind not in {"contains", "all"}:
        return False
    value_keys = [key for key in ("value", "values", "terms") if key in rule]
    if len(value_keys) != 1:
        return False
    selected_key = value_keys[0]
    raw_values = [rule.get("value")] if selected_key == "value" else rule.get(selected_key)
    if not isinstance(raw_values, list) or not 1 <= len(raw_values) <= 100:
        return False
    values = [item for item in raw_values if isinstance(item, str) and item.strip() and len(item) <= 1000]
    if len(values) != len(raw_values):
        return False
    return True


def _acl_allows(entry: dict[str, Any], tenant_id: str, groups: set[str], subject_id: str) -> bool:
    if str(entry.get("tenant_id") or "") != tenant_id:
        return False
    acl = entry.get("acl") if isinstance(entry.get("acl"), dict) else {}
    visibility = str(acl.get("visibility") or "").lower()
    if visibility not in ALLOWED_VISIBILITY:
        return False
    if visibility == "tenant":
        return True
    if visibility == "group":
        allowed = {item.lower() for item in _strings(acl.get("groups"), maximum=200)}
        return bool(allowed & groups)
    subjects = set(_strings(acl.get("subjects"), maximum=200))
    return bool(subject_id) and subject_id in subjects


def _work_text(work_definition: dict[str, Any]) -> str:
    """Project only approval-bound semantic fields into deterministic trigger text."""
    fields: list[str] = []
    item_text_keys = (
        "value", "title", "name", "description", "capability", "action", "condition", "risk", "control",
        "label", "current_work", "problem", "problems", "improvement", "exception", "resolution", "criterion",
    )

    def append_semantic(value: Any, depth: int = 0) -> None:
        if depth > 4:
            return
        if isinstance(value, str):
            if value.strip():
                fields.append(value)
            return
        if isinstance(value, list):
            for item in value[:100]:
                append_semantic(item, depth + 1)
            return
        if isinstance(value, dict):
            for name in item_text_keys:
                if name in value:
                    append_semantic(value.get(name), depth + 1)

    for key in ("goal", "trigger", "frequency_volume", "sla", "automation_intent"):
        append_semantic(work_definition.get(key))
    for key in (
        "scope_in", "scope_out", "actors", "systems", "inputs", "outputs", "steps", "decisions", "exceptions",
        "pains", "risks_controls", "constraints", "success_criteria", "assumptions", "unresolved",
    ):
        value = work_definition.get(key)
        if isinstance(value, list):
            append_semantic(value)
    graph = work_definition.get("as_is_graph")
    if isinstance(graph, dict):
        for node in list(graph.get("nodes") or [])[:200]:
            append_semantic(node)
        for edge in list(graph.get("edges") or [])[:500]:
            append_semantic(edge)
    return "\n".join(fields).lower()[:100000]


def _rule_matches(rule: Any, text: str) -> bool:
    if isinstance(rule, str):
        return rule.strip().lower() in text if rule.strip() else False
    if not isinstance(rule, dict):
        return False
    kind = str(rule.get("kind") or "contains").lower()
    values = [item.lower() for item in _strings(rule.get("values") or rule.get("terms"))]
    if not values:
        value = str(rule.get("value") or "").strip().lower()
        values = [value] if value else []
    if kind == "all":
        return bool(values) and all(value in text for value in values)
    if kind == "regex":
        return False
    return any(value in text for value in values)


def resolve_skill_context(
    work_definition: Any,
    skill_registry: Any,
    *,
    tenant_id: str = "",
    acl_context: Any = None,
    requested_skill_refs: Any = None,
    max_skills: int = 8,
    max_context_chars: int = 24000,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    supplied = _payload(work_definition)
    design_scope = supplied if isinstance(supplied, dict) and supplied.get("schema_version") == "agent-design-scope/v1" else {}
    if design_scope:
        supplied_hash = str(design_scope.get("design_scope_sha256") or "")
        if (
            design_scope.get("ok") is not True
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", supplied_hash)
            or not hmac.compare_digest(supplied_hash, _scope_hash(design_scope))
        ):
            return _error(trace_id, "DESIGN_SCOPE_INVALID", "검증·봉인된 design scope가 필요합니다.")
        work = _payload(design_scope.get("work_definition"))
        acl = _payload(design_scope.get("acl_context"))
        tenant = str(design_scope.get("tenant_id") or "").strip()
    else:
        work = supplied
        acl = _payload(acl_context)
        tenant = str(tenant_id or "").strip()
    registry, registry_error = _approved_registry_items(skill_registry)
    requested = _items(requested_skill_refs, "skills", "items", "requested_skills")
    groups = {item.lower() for item in _strings(acl.get("groups") if isinstance(acl, dict) else [])}
    subject_id = str(acl.get("subject_id") or "") if isinstance(acl, dict) else ""
    if not tenant:
        return _error(trace_id, "TENANT_REQUIRED", "tenant_id가 필요합니다.")
    if not isinstance(work, dict) or not work:
        return _error(trace_id, "INVALID_WORK_DEFINITION", "업무 정의가 비어 있거나 잘못되었습니다.")
    if not isinstance(acl, dict) or not acl.get("subject_id"):
        return _error(trace_id, "ACL_CONTEXT_MISSING", "검증 가능한 ACL context가 필요합니다.")
    if registry_error:
        messages = {
            "SKILL_REGISTRY_EMPTY": "승인 Skill registry가 제공되지 않았습니다.",
            "SKILL_REGISTRY_UPSTREAM_FAILED": "승인 Skill registry를 제공한 상위 단계가 실패했습니다.",
            "SKILL_REGISTRY_CONTRACT_INVALID": "승인 Skill registry 형식이 유효하지 않습니다.",
        }
        return _error(trace_id, registry_error, messages[registry_error])

    max_skills = max(1, min(20, int(max_skills or 8)))
    max_context_chars = max(1000, min(100000, int(max_context_chars or 24000)))
    requested_map = {
        (
            _safe_trace_identity(item.get("skill_id"), skill_id=True),
            _safe_trace_identity(item.get("version")),
        ): str(item.get("prompt_sha256") or "")[:80]
        for item in requested
    }
    text = _work_text(work)
    applied: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    context_parts: list[str] = []
    used_chars = 0
    identity_counts: dict[tuple[str, str], int] = {}
    for entry in registry:
        identity = (
            _safe_trace_identity(entry.get("skill_id"), skill_id=True),
            _safe_trace_identity(entry.get("version")),
        )
        identity_counts[identity] = identity_counts.get(identity, 0) + 1

    for entry in registry:
        skill_id = _safe_trace_identity(entry.get("skill_id"), skill_id=True)
        version = _safe_trace_identity(entry.get("version"))
        prompt_text = entry.get("prompt_text") if isinstance(entry.get("prompt_text"), str) else ""
        identity = (skill_id, version)
        reason = _registry_contract_error(entry)
        if not reason and identity_counts.get(identity, 0) > 1:
            reason = "DUPLICATE_SKILL_IDENTITY"
        if not reason and (not skill_id or not version):
            reason = "INVALID_REGISTRY_IDENTITY"
        if not reason and entry.get("status") != "active":
            reason = "SKILL_NOT_ACTIVE"
        if not reason and not _acl_allows(entry, tenant, groups, subject_id):
            reason = "SKILL_ACL_DENIED"
        if not reason and not _hash_matches(entry.get("prompt_sha256"), prompt_text):
            reason = "SKILL_HASH_MISMATCH"
        if not reason and any(pattern.search(prompt_text) for pattern in SECRET_VALUE_PATTERNS):
            reason = "SKILL_SECRET_MATERIAL_DETECTED"
        surfaced_values = (
            entry.get("name"), entry.get("version"), entry.get("match_reason"), entry.get("target_stage")
        )
        if not reason and any(
            isinstance(value, str) and any(pattern.search(value) for pattern in SECRET_VALUE_PATTERNS)
            for value in surfaced_values
        ):
            reason = "SKILL_SECRET_MATERIAL_DETECTED"
        if not reason and any(re.search(pattern, prompt_text) for pattern in FORBIDDEN_INSTRUCTION_PATTERNS):
            reason = "UNSAFE_SKILL_INSTRUCTION"
        if not reason:
            requested_hash = requested_map.get((skill_id, version))
            if requested and requested_hash is None:
                reason = "SKILL_NOT_REQUESTED"
            elif requested and not re.fullmatch(r"(?:sha256:)?[0-9a-f]{64}", str(requested_hash).lower()):
                reason = "REQUESTED_SKILL_HASH_REQUIRED"
            elif requested_hash and requested_hash.lower() not in {
                str(entry.get("prompt_sha256") or "").lower(),
                str(entry.get("prompt_sha256") or "").lower().removeprefix("sha256:"),
            }:
                reason = "REQUESTED_SKILL_HASH_MISMATCH"

        trigger_rules = entry.get("trigger_rules") if isinstance(entry.get("trigger_rules"), list) else []
        near_miss_rules = entry.get("near_miss_rules") if isinstance(entry.get("near_miss_rules"), list) else []
        trigger_match = any(_rule_matches(rule, text) for rule in trigger_rules[:100]) if not reason and trigger_rules else bool(requested)
        near_miss_match = any(_rule_matches(rule, text) for rule in near_miss_rules[:100]) if not reason else False
        if not reason and not trigger_match:
            reason = "TRIGGER_NOT_MATCHED"
        if not reason and near_miss_match:
            reason = "NEAR_MISS_MATCHED"

        if reason:
            rejected.append({"skill_id": skill_id, "version": version, "reason": reason})
            continue
        framed = (
            f'<approved-skill id="{skill_id}" version="{version}" '
            f'hash="{entry.get("prompt_sha256")}">\n{prompt_text}\n</approved-skill>'
        )
        if len(applied) >= max_skills or used_chars + len(framed) > max_context_chars:
            rejected.append({"skill_id": skill_id, "version": version, "reason": "SKILL_CONTEXT_LIMIT"})
            continue
        match_reason = str(entry.get("match_reason") or "trigger rule matched")[:500]
        applied.append(
            {
                "skill_id": skill_id,
                "name": str(entry.get("name") or skill_id)[:200],
                "version": version,
                "prompt_sha256": str(entry.get("prompt_sha256")),
                "match_reason": match_reason,
                "target_stage": str(entry.get("target_stage") or "design")[:100],
                "source_ref": "approved-skill-registry",
            }
        )
        context_parts.append(framed)
        used_chars += len(framed)

    return {
        "ok": True,
        "status": "COMPLETED",
        "tenant_id": tenant,
        "catalog_snapshot_id": str(design_scope.get("catalog_snapshot_id") or ""),
        "work_definition_id": str(design_scope.get("work_definition_id") or work.get("work_definition_id") or ""),
        "work_definition_revision": design_scope.get("work_definition_revision") if design_scope else work.get("revision"),
        "approved_hash": str(design_scope.get("approved_hash") or work.get("approved_hash") or ""),
        "design_scope_sha256": str(design_scope.get("design_scope_sha256") or ""),
        "approved_skill_context": "\n\n".join(context_parts),
        "applied_skills": applied,
        "rejected_skills": rejected,
        "context_char_count": used_chars,
        "trust_boundary": {
            "source": "approved-skill-registry",
            "policy_precedence": "system_policy_over_skill_context",
            "dynamic_tool_addition": False,
            "secret_access": False,
        },
        "trace_id": trace_id,
    }


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


class SkillContextResolverComponent(Component):
    display_name = "19 Approved Skill Context Resolver"
    description = "승인 registry의 Skill ID/version/hash, trigger, near-miss, ACL을 검증해 bounded context를 만듭니다."
    icon = "ShieldCheck"
    name = "SkillContextResolver"

    inputs = [
        DataInput(name="design_scope", display_name="Sealed Design Scope", required=True),
        DataInput(name="skill_registry", display_name="Approved Skill Registry", required=True),
        DataInput(name="requested_skill_refs", display_name="Requested Skill Refs", required=False, advanced=True),
        IntInput(name="max_skills", display_name="Maximum Skills", value=8, advanced=True),
        IntInput(name="max_context_chars", display_name="Maximum Context Characters", value=24000, advanced=True),
    ]
    outputs = [Output(name="skill_context", display_name="Verified Skill Context", method="build_skill_context", types=["Data"])]

    def build_skill_context(self) -> Data:
        result = resolve_skill_context(
            self.design_scope,
            self.skill_registry,
            requested_skill_refs=getattr(self, "requested_skill_refs", None),
            max_skills=getattr(self, "max_skills", 8),
            max_context_chars=getattr(self, "max_context_chars", 24000),
        )
        self.status = f"Skill resolve: {result.get('status')} / applied={len(result.get('applied_skills', []))}"
        return Data(data=result)

from __future__ import annotations

import copy
import hashlib
import hmac
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data


ALLOWED_ASSET_TYPES = {"component", "flow"}
DESIGN_INVOCATION_SCHEMA_VERSION = "agent-design-invocation/v1"
DESIGN_INVOCATION_KEYS = {
    "ok",
    "status",
    "schema_version",
    "artifact_refs",
    "tenant_id",
    "work_definition_id",
    "work_definition_revision",
    "approved_hash",
    "owner_id",
    "session_id",
    "catalog_snapshot_id",
    "work_definition",
    "acl_context",
    "skill_registry",
    "design_prompt",
    "search_seed",
    "trust_boundary",
    "trace_id",
}
# Langflow 1.11 can preserve a Data payload's fields while also adding the
# Data.get_text() projection and a blank default value to a nested Run Flow
# ChatInput.  This is the *only* transport shell accepted at the F10 -> F20
# boundary; all other extra fields remain forbidden by the invocation schema.
F10_RUN_FLOW_TRANSPORT_KEYS = {"text", "default_value"}
SECRET_VALUE_PATTERNS = (
    re.compile(r"(?i)\b(?:api[_-]?key|password|passwd|secret|access[_-]?token|client[_-]?secret|authorization|cookie|session)\s*[:=]\s*[\"']?[^\s,;]{8,}"),
    re.compile(r"(?i)\b(?:bearer|basic)\s+\S{8,}"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\b[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"[a-zA-Z][a-zA-Z0-9+.-]*://[^/@\s]+:[^/@\s]+@"),
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
)
SECRET_KEY_TOKENS = {
    "apikey", "authorization", "clientsecret", "cookie", "credential", "password", "passwd",
    "privatekey", "pwd", "session", "smsession", "secret", "token",
}
ALLOWED_QUERY_KINDS = {"purpose", "capability", "exact", "risk", "reporting"}
WORK_DEFINITION_SCHEMA_VERSION = "work-definition/v1"
IDENTITY_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")
SHA256_PATTERN = re.compile(r"^sha256:[0-9a-f]{64}$")
MAX_SEARCH_SEED_CHARS = 4000
SEMANTIC_FIELDS = (
    "goal",
    "trigger",
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "decisions",
    "exceptions",
    "frequency_volume",
    "sla",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "automation_intent",
    "assumptions",
    "unresolved",
    "as_is_graph",
)
UNORDERED_LIST_KEYS = {
    "scope_in", "scope_out", "actors", "systems", "inputs", "outputs", "pains", "risks_controls",
    "constraints", "success_criteria", "assumptions", "unresolved", "nodes", "edges", "evidence_turn_ids",
    "conflicting_values",
}
NON_SEMANTIC_KEYS = {
    "x", "y", "position", "position_absolute", "style", "selected", "expanded", "display_order",
    "created_at", "updated_at", "submitted_at", "expires_at", "trace_id", "run_id", "job_id",
    "last_updated_revision", "confidence", "evidence_turn_ids", "processed_answer_batches",
}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _unwrap_f10_run_flow_transport(value: Any) -> dict[str, Any]:
    """Return the canonical F10 invocation from Langflow's narrow Data shell.

    Component 36 serializes the canonical ``agent-design-invocation/v1`` into
    its ``text`` field so a nested Run Flow can feed F20's Chat Input.  In
    Langflow 1.11, the child can instead receive a shell that contains both
    the original fields and ``{"text": <canonical-json>, "default_value": ""}``.

    Accepting an arbitrary text-bearing wrapper here would weaken F20's
    authority boundary.  Therefore this helper unwraps only that exact shape,
    requires byte-for-byte canonical JSON, and verifies that every duplicated
    canonical field agrees before the normal strict validation runs.
    """

    outer = _payload(value)
    if "text" not in outer or outer.get("default_value") != "":
        return outer
    if set(outer) - (DESIGN_INVOCATION_KEYS | F10_RUN_FLOW_TRANSPORT_KEYS):
        return outer

    serialized = outer.get("text")
    if not isinstance(serialized, str) or not serialized:
        return outer
    try:
        inner = json.loads(serialized)
    except json.JSONDecodeError:
        return outer
    if not isinstance(inner, dict):
        return outer
    if set(outer) != set(inner) | F10_RUN_FLOW_TRANSPORT_KEYS:
        return outer
    try:
        canonical = json.dumps(
            inner,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError):
        return outer
    if serialized != canonical:
        return outer
    if any(outer.get(key) != item for key, item in inner.items()):
        return outer
    return inner


def _text_field(value: Any) -> tuple[str, str]:
    if isinstance(value, str):
        return value.strip(), "unknown"
    if isinstance(value, dict):
        return str(value.get("value") or value.get("text") or "").strip(), str(value.get("status") or "unknown")
    return "", "unknown"


def _safe_text(value: Any, maximum: int = 2000) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()[:maximum]


def _search_seed_object(value: Any) -> dict[str, Any] | None:
    """Unwrap only the Langflow bridge forms used for a search seed.

    F10 is normally connected to F20 through ``Data -> Message -> JSON``.
    Older imported copies of the F10 Flow can therefore reach F20 as a JSON
    string or as a narrow ``Data({"text": ...})`` wrapper.  The helper does
    not accept arbitrary objects: after unwrapping, the strict schema checks
    below still decide whether the seed is usable.
    """

    if isinstance(value, dict):
        candidate: Any = copy.deepcopy(value)
    else:
        data = getattr(value, "data", None)
        if isinstance(data, dict):
            candidate = copy.deepcopy(data)
        else:
            text = getattr(value, "text", value if isinstance(value, str) else None)
            if not isinstance(text, str) or not text.strip():
                return None
            try:
                candidate = json.loads(text)
            except json.JSONDecodeError:
                return None

    # Some Langflow 1.11 bridge variants preserve the Message/Data shell as a
    # single ``{"text": "{...}"}`` or ``{"data": {...}}`` object.  Peel
    # only those exact, bounded shells; do not generically traverse arbitrary
    # user-controlled dictionaries.  The strict seed schema below still
    # validates the resulting object and its SHA-256 before use.
    for _ in range(2):
        if not isinstance(candidate, dict):
            return None
        if set(candidate) == {"text"} and isinstance(candidate.get("text"), str):
            if not candidate["text"].strip():
                return {}
            try:
                candidate = json.loads(candidate["text"])
            except json.JSONDecodeError:
                return None
            continue
        if set(candidate) == {"data"} and isinstance(candidate.get("data"), dict):
            candidate = copy.deepcopy(candidate["data"])
            continue
        break
    return copy.deepcopy(candidate) if isinstance(candidate, dict) else None


def _canonical_search_seed(text: Any, supplied_hash: Any, *, legacy: bool) -> dict[str, str]:
    if not isinstance(text, str) or not text.strip() or len(text) > 50_000:
        raise ValueError("SEARCH_SEED_INVALID")
    if legacy:
        # Legacy F10 stored the hash for the original request text.  Current
        # F20 uses a whitespace-normalized, bounded retrieval projection, so
        # validate the old value first and then seal the new projection.
        expected_raw = hashlib.sha256(text.encode("utf-8")).hexdigest()
        if (
            not isinstance(supplied_hash, str)
            or re.fullmatch(r"(?:sha256:)?[0-9a-f]{64}", supplied_hash) is None
            or not hmac.compare_digest(supplied_hash.removeprefix("sha256:"), expected_raw)
        ):
            raise ValueError("SEARCH_SEED_HASH_MISMATCH")
        text = re.sub(r"\s+", " ", text).strip()[:MAX_SEARCH_SEED_CHARS]
        supplied_hash = "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()
    if not isinstance(text, str) or not text.strip() or len(text) > MAX_SEARCH_SEED_CHARS:
        raise ValueError("SEARCH_SEED_INVALID")
    if not isinstance(supplied_hash, str) or SHA256_PATTERN.fullmatch(supplied_hash) is None:
        raise ValueError("SEARCH_SEED_INVALID")
    expected_hash = "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()
    if not hmac.compare_digest(supplied_hash, expected_hash):
        raise ValueError("SEARCH_SEED_HASH_MISMATCH")
    if any(pattern.search(text) for pattern in SECRET_VALUE_PATTERNS):
        raise ValueError("SEARCH_SEED_SECRET_MATERIAL_DETECTED")
    return {"text": text, "sha256": supplied_hash}


def _validated_search_seed(value: Any) -> dict[str, str]:
    """Accept the current sealed seed and narrow, verified legacy forms.

    The seed is retrieval-only and never becomes an approved WorkDefinition
    fact or Blueprint instruction.  An absent or deliberately empty legacy
    seed falls back to the approved structured work fields.  A populated but
    malformed seed still fails closed rather than silently influencing search.
    """

    if value is None or (isinstance(value, str) and not value.strip()):
        return {}
    seed = _search_seed_object(value)
    if seed is None:
        raise ValueError("SEARCH_SEED_INVALID")
    # An older Flow with no source request can surface this exact transport
    # shell instead of omitting the optional field.  It has no retrieval text,
    # so treating it as an absent seed is equivalent to the documented
    # approved-WorkDefinition fallback and cannot inject search instructions.
    if not seed or (
        set(seed) == {"text"}
        and isinstance(seed.get("text"), str)
        and not seed["text"].strip()
    ):
        return {}

    canonical_fields = {"text", "sha256", "source", "truncated"}
    if set(seed) <= canonical_fields and "text" in seed:
        source = seed.get("source")
        truncated = seed.get("truncated")
        if source not in (None, "validated_original_work_request") or (
            truncated is not None and type(truncated) is not bool
        ):
            raise ValueError("SEARCH_SEED_INVALID")
        return _canonical_search_seed(seed.get("text"), seed.get("sha256"), legacy=False)

    # Compatibility for an already-approved F10 execution generated before
    # the current ``text/source/truncated`` projection was introduced.  It
    # may be passed directly or under one explicit ``source_request`` wrapper.
    if set(seed) == {"source_request"} and isinstance(seed.get("source_request"), dict):
        seed = copy.deepcopy(seed["source_request"])
    legacy_fields = {"turn_id", "raw_text", "language", "submitted_at", "sha256"}
    if set(seed) <= legacy_fields and "raw_text" in seed:
        return _canonical_search_seed(seed.get("raw_text"), seed.get("sha256"), legacy=True)

    raise ValueError("SEARCH_SEED_INVALID")


def _is_identity(value: Any) -> bool:
    return type(value) is str and IDENTITY_PATTERN.fullmatch(value) is not None


def _secret_key(value: Any) -> bool:
    text = str(value or "").casefold()
    compact = re.sub(r"[^a-z0-9]", "", text)
    parts = {item for item in re.split(r"[^a-z0-9]+", text) if item}
    if ("token" in parts and parts & {"max", "limit", "budget", "count"}) or (
        "session" in parts and parts & {"timeout", "ttl"}
    ):
        return False
    if "token" in compact and any(marker in compact for marker in {"maxtoken", "tokenlimit", "tokenbudget", "tokencount"}):
        return False
    if "session" in compact and any(marker in compact for marker in {"sessiontimeout", "sessionttl"}):
        return False
    return compact in SECRET_KEY_TOKENS or bool(parts & {"token", "session", "pwd"}) or any(
        marker in compact for marker in SECRET_KEY_TOKENS
    )


def _secret_material_kind(value: Any) -> str | None:
    if isinstance(value, dict):
        for key, item in value.items():
            if any(pattern.search(str(key).strip()) for pattern in SECRET_VALUE_PATTERNS):
                return "object_key"
            if _secret_key(key):
                return "secret_field"
            found = _secret_material_kind(item)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = _secret_material_kind(item)
            if found:
                return found
    elif isinstance(value, str) and value != "[REDACTED]" and any(
        pattern.search(value.strip()) for pattern in SECRET_VALUE_PATTERNS
    ):
        return "string_value"
    return None


def _canonical_hash(value: Any) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


def _canonicalize(value: Any, parent_key: str = "") -> Any:
    if isinstance(value, dict):
        return {
            key: _canonicalize(value[key], key)
            for key in sorted(value)
            if key not in NON_SEMANTIC_KEYS and not key.startswith("ui_") and not key.startswith("render_")
        }
    if isinstance(value, list):
        items = [_canonicalize(item, parent_key) for item in value]
        if parent_key in UNORDERED_LIST_KEYS:
            items.sort(key=lambda item: json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str))
        return items
    if isinstance(value, float):
        return float(format(value, ".15g"))
    return value


def _approved_work_projection(work: dict[str, Any]) -> tuple[dict[str, Any], str]:
    semantic = {field: copy.deepcopy(work.get(field)) for field in SEMANTIC_FIELDS}
    # Match Component 17's approval hash without breaking records approved
    # before F10 stored resumable intake context.  When present, the context
    # remains in the sealed F20 scope but is never invented from a chat reply.
    if "f10_design_context" in work:
        semantic["f10_design_context"] = copy.deepcopy(work.get("f10_design_context"))
    canonical_semantic = _canonicalize(semantic)
    canonical_text = json.dumps(
        canonical_semantic,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    actual_hash = "sha256:" + hashlib.sha256(canonical_text.encode("utf-8")).hexdigest()
    projection = {
        "schema_version": str(work.get("schema_version") or "work-definition/v1"),
        "work_definition_id": str(work.get("work_definition_id") or ""),
        "tenant_id": str(work.get("tenant_id") or ""),
        "owner_id": str(work.get("owner_id") or ""),
        "session_id": str(work.get("session_id") or ""),
        "channel_mode": str(work.get("channel_mode") or ""),
        "revision": work.get("revision"),
        "status": "APPROVED",
        "approved_hash": actual_hash,
        "preview_hash": actual_hash,
        **canonical_semantic,
    }
    return projection, actual_hash


def _confirmed_terms(value: Any, maximum: int = 30) -> list[str]:
    source = value if isinstance(value, list) else []
    result: list[str] = []
    for item in source[:maximum]:
        if isinstance(item, dict):
            provenance = item.get("provenance") if isinstance(item.get("provenance"), dict) else {}
            status = str(item.get("status") or item.get("provenance_status") or provenance.get("status") or "unknown").lower()
            if status not in {"confirmed", "approved"}:
                continue
            text = _safe_text(item.get("name") or item.get("title") or item.get("value"), 200)
        else:
            continue
        if text and text not in result:
            result.append(text)
    return result


def build_design_scope(
    work_definition: Any,
    *,
    tenant_id: str,
    catalog_snapshot_id: str,
    acl_context: Any,
    design_prompt: str = "",
    search_seed: Any = None,
) -> dict[str, Any]:
    """Validate and seal every approved design input into one typed scope.

    F20 exposes these values only on this component. Downstream components
    receive this immutable identity tuple instead of independent node tweaks.
    """
    trace_id = str(uuid.uuid4())
    work = _payload(work_definition)
    acl = _payload(acl_context)
    tenant = _safe_text(tenant_id, 200)
    snapshot = _safe_text(catalog_snapshot_id, 200)
    bounded_design_prompt = _safe_text(design_prompt, 4000)
    try:
        validated_seed = _validated_search_seed(search_seed)
    except ValueError as exc:
        code = str(exc)
        message = {
            "SEARCH_SEED_INVALID": "원문 업무 설명 기반 검색 seed 형식이 유효하지 않습니다.",
            "SEARCH_SEED_HASH_MISMATCH": "원문 업무 설명 기반 검색 seed hash가 일치하지 않습니다.",
            "SEARCH_SEED_SECRET_MATERIAL_DETECTED": "원문 업무 설명 기반 검색 seed에 secret 원문을 넣을 수 없습니다.",
        }.get(code, "원문 업무 설명 기반 검색 seed를 검증할 수 없습니다.")
        return _error(trace_id, code if code.startswith("SEARCH_SEED_") else "SEARCH_SEED_INVALID", message)
    if not _is_identity(tenant_id):
        return _error(trace_id, "TENANT_REQUIRED", "tenant_id가 필요합니다.")
    if not _is_identity(catalog_snapshot_id):
        return _error(trace_id, "CATALOG_SNAPSHOT_ID_INVALID", "활성 catalog snapshot ID 형식이 유효하지 않습니다.")
    if set(acl) - {"subject_id", "groups"}:
        return _error(trace_id, "ACL_CONTEXT_FIELDS_INVALID", "ACL context에 허용되지 않은 필드가 있습니다.")
    raw_groups = acl.get("groups", [])
    if (
        not _is_identity(acl.get("subject_id"))
        or not isinstance(raw_groups, list)
        or len(raw_groups) > 100
        or any(not _is_identity(item) for item in raw_groups)
    ):
        return _error(trace_id, "ACL_CONTEXT_IDENTITY_INVALID", "ACL subject와 group identity 형식이 유효하지 않습니다.")
    if _secret_material_kind(acl):
        return _error(trace_id, "ACL_CONTEXT_SECRET_MATERIAL_DETECTED", "ACL context에 secret 원문을 넣을 수 없습니다.")
    canonical_acl = {
        "subject_id": str(acl["subject_id"]),
        "groups": sorted({str(item).lower() for item in raw_groups}),
    }
    if not work:
        return _error(trace_id, "INVALID_WORK_DEFINITION", "승인 업무 정의가 필요합니다.")
    if any(pattern.search(bounded_design_prompt) for pattern in SECRET_VALUE_PATTERNS):
        return _error(
            trace_id,
            "DESIGN_PROMPT_SECRET_MATERIAL_DETECTED",
            "추가 설계 프롬프트에는 secret 원문을 넣을 수 없습니다.",
        )
    if type(work.get("schema_version")) is not str or work.get("schema_version") != WORK_DEFINITION_SCHEMA_VERSION:
        return _error(
            trace_id,
            "WORK_DEFINITION_SCHEMA_INVALID",
            f"승인 업무 정의 schema_version은 {WORK_DEFINITION_SCHEMA_VERSION}이어야 합니다.",
        )
    for field in ("tenant_id", "owner_id", "session_id", "work_definition_id"):
        if not _is_identity(work.get(field)):
            return _error(
                trace_id,
                "WORK_DEFINITION_IDENTITY_INVALID",
                f"승인 업무 정의 {field}가 canonical identity 형식이 아닙니다.",
            )
    if work.get("channel_mode") != "native_hitl":
        return _error(trace_id, "WORK_DEFINITION_CHANNEL_INVALID", "승인 업무 정의 channel_mode가 유효하지 않습니다.")
    state = work.get("status")
    approved_hash = work.get("approved_hash")
    work_id = work.get("work_definition_id")
    raw_revision = work.get("revision")
    if type(raw_revision) is not int:
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 필요합니다.")
    work_revision = raw_revision
    if work_revision < 0:
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 필요합니다.")
    if state != "APPROVED" or type(approved_hash) is not str or not re.fullmatch(r"sha256:[0-9a-f]{64}", approved_hash):
        return _error(trace_id, "WORK_DEFINITION_NOT_APPROVED", "approved 상태와 유효한 approved_hash가 필요합니다.")
    if work.get("tenant_id") != tenant:
        return _error(trace_id, "WORK_DEFINITION_TENANT_MISMATCH", "승인 업무 정의 tenant가 설계 tenant와 다릅니다.")
    try:
        approved_work, actual_approved_hash = _approved_work_projection(work)
    except (TypeError, ValueError):
        return _error(trace_id, "WORK_DEFINITION_CANONICALIZATION_FAILED", "승인 업무 정의의 의미 필드를 canonicalize할 수 없습니다.")
    if not hmac.compare_digest(approved_hash.lower(), actual_approved_hash.lower()):
        return _error(trace_id, "WORK_DEFINITION_APPROVAL_HASH_MISMATCH", "승인 이후 업무 의미가 변경되었거나 승인 hash가 유효하지 않습니다.")
    semantic_secret_kind = _secret_material_kind(
        {field: approved_work.get(field) for field in SEMANTIC_FIELDS}
    )
    if semantic_secret_kind:
        return _error(
            trace_id,
            "WORK_DEFINITION_SECRET_MATERIAL_DETECTED",
            "승인 업무 정의의 의미 필드에 secret 원문이 포함되어 설계를 중단했습니다.",
        )
    scope_core = {
        "schema_version": "agent-design-scope/v1",
        "tenant_id": tenant,
        "catalog_snapshot_id": snapshot,
        "work_definition_id": work_id,
        "work_definition_revision": work_revision,
        "approved_hash": approved_hash,
        "work_definition": approved_work,
        "acl_context": canonical_acl,
        "design_prompt": bounded_design_prompt,
    }
    if validated_seed:
        # Preserve only a hash in the durable scope.  The raw text is consumed
        # by the query planner below and never becomes Blueprint prompt input.
        scope_core["search_seed_sha256"] = validated_seed["sha256"]
    return {
        "ok": True,
        "status": "COMPLETED",
        **scope_core,
        "design_scope_sha256": _canonical_hash(scope_core),
        "trace_id": trace_id,
    }


def _step_items(value: Any, maximum: int = 100) -> list[dict[str, str]]:
    source = value if isinstance(value, list) else []
    result: list[dict[str, str]] = []
    for index, item in enumerate(source[:maximum], start=1):
        if not isinstance(item, dict):
            continue
        step_id = _safe_text(item.get("step_id") or item.get("id") or f"step-{index}", 100)
        title = _safe_text(item.get("title") or item.get("name"), 300)
        capability = _safe_text(item.get("capability") or item.get("description") or item.get("action"), 1000)
        if title or capability:
            result.append({"step_id": step_id, "title": title, "capability": capability})
    return result


def build_search_query_plan(
    work_definition: Any,
    *,
    tenant_id: str,
    catalog_snapshot_id: str,
    acl_context: Any,
    design_prompt: str = "",
    search_seed: Any = None,
    max_queries: int = 30,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    scope = build_design_scope(
        work_definition,
        tenant_id=tenant_id,
        catalog_snapshot_id=catalog_snapshot_id,
        acl_context=acl_context,
        design_prompt=design_prompt,
        search_seed=search_seed,
    )
    if not scope.get("ok"):
        return scope
    work = scope["work_definition"]
    acl = scope["acl_context"]
    tenant = scope["tenant_id"]
    snapshot = scope["catalog_snapshot_id"]
    approved_hash = scope["approved_hash"]

    max_queries = max(1, min(50, int(max_queries or 30)))
    goal, _ = _text_field(work.get("goal") or work.get("purpose"))
    title, _ = _text_field(work.get("title"))
    steps = _step_items(work.get("steps") or (work.get("as_is_graph") or {}).get("nodes"))
    systems = _confirmed_terms(work.get("systems"))
    inputs = _confirmed_terms(work.get("inputs"))
    outputs = _confirmed_terms(work.get("outputs"))
    risks = _confirmed_terms(work.get("risks_controls"))
    prompt = scope["design_prompt"]
    try:
        validated_seed = _validated_search_seed(search_seed)
    except ValueError as exc:
        return _error(trace_id, str(exc), "원문 업무 설명 기반 검색 seed를 검증할 수 없습니다.")
    queries: list[dict[str, Any]] = []

    def add(kind: str, text: str, expected: list[str], purpose: str, step_ids: list[str] | None = None) -> None:
        clean = _safe_text(text, 2000)
        if not clean or kind not in ALLOWED_QUERY_KINDS or len(queries) >= max_queries:
            return
        identity = {"kind": kind, "text": clean, "expected": expected, "step_ids": step_ids or []}
        query_id = "q-" + hashlib.sha256(json.dumps(identity, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:16]
        if any(item["query_id"] == query_id for item in queries):
            return
        queries.append(
            {
                "query_id": query_id,
                "kind": kind,
                "text": clean,
                "purpose": _safe_text(purpose, 500),
                "expected_asset_types": [item for item in expected if item in ALLOWED_ASSET_TYPES],
                "matched_work_steps": step_ids or [],
                "required_filters": {
                    "tenant_id": tenant,
                    "snapshot_id": snapshot,
                    "acl_required": True,
                },
            }
        )

    add("purpose", " ".join(item for item in (title, goal, prompt) if item), ["component", "flow"], "전체 업무 목적과 유사한 자산 탐색")
    if validated_seed:
        add(
            "purpose",
            validated_seed["text"],
            ["component", "flow"],
            "원문 업무 설명 기반 재사용 후보 탐색",
        )
    for step in steps:
        add(
            "capability",
            " ".join(item for item in (step["title"], step["capability"]) if item),
            ["component", "flow"],
            "업무 단계 capability 충족 자산 탐색",
            [step["step_id"]],
        )
    for system in systems:
        add("exact", system, ["component", "flow"], "사용자가 확인한 시스템/API/제품명 exact 또는 alias 탐색")
    for input_name in inputs:
        add("capability", input_name, ["component", "flow"], "확인된 입력 데이터·문서·시스템을 처리할 수 있는 자산 탐색")
    for risk in risks:
        add("risk", risk, ["component", "flow"], "승인·보안·예외 처리 capability 탐색")
    if outputs:
        add("reporting", " ".join(outputs), ["component", "flow"], "업무 출력과 보고 capability 탐색")
    if not queries:
        return _error(trace_id, "NO_SEARCHABLE_REQUIREMENT", "검색 query를 만들 확인된 업무 정보가 없습니다.")

    plan_core = {
        "schema_version": "search-query-plan.v1",
        "tenant_id": tenant,
        "catalog_snapshot_id": snapshot,
        "work_definition_id": str(work.get("work_definition_id") or ""),
        "work_definition_revision": scope["work_definition_revision"],
        "approved_hash": approved_hash,
        "design_scope_sha256": scope["design_scope_sha256"],
        "acl": {
            "subject_id": str(acl.get("subject_id")),
            "groups": sorted(_confirmed_acl_groups(acl.get("groups"))),
        },
        "queries": queries,
        "confirmed_exact_terms": systems,
        "confirmed_inputs": inputs,
        "confirmed_outputs": outputs,
    }
    if scope.get("search_seed_sha256"):
        plan_core["search_seed_sha256"] = str(scope["search_seed_sha256"])
    return {
        "ok": True,
        "status": "COMPLETED",
        **plan_core,
        "query_plan_sha256": _canonical_hash(plan_core),
        "trace_id": trace_id,
    }


def _confirmed_acl_groups(value: Any) -> set[str]:
    source = value if isinstance(value, list) else []
    return {str(item).strip().lower() for item in source[:100] if str(item).strip()}


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


def validate_design_invocation(value: Any) -> dict[str, Any]:
    """Validate the single trusted input exposed by F20 and Run Flow."""

    trace_id = str(uuid.uuid4())
    invocation = _unwrap_f10_run_flow_transport(value)
    if invocation.get("ok") is not True or invocation.get("status") != "READY_FOR_DESIGN":
        return _error(trace_id, "DESIGN_INVOCATION_NOT_READY", "MongoDB 권위 데이터 재확인이 완료된 invocation이 필요합니다.")
    if invocation.get("schema_version") != DESIGN_INVOCATION_SCHEMA_VERSION:
        return _error(trace_id, "DESIGN_INVOCATION_SCHEMA_INVALID", "승인 설계 invocation schema가 유효하지 않습니다.")
    if set(invocation) - DESIGN_INVOCATION_KEYS:
        return _error(trace_id, "DESIGN_INVOCATION_FIELDS_INVALID", "승인 설계 invocation에 허용되지 않은 필드가 있습니다.")
    work = _payload(invocation.get("work_definition"))
    acl = _payload(invocation.get("acl_context"))
    registry_payload = invocation.get("skill_registry")
    if isinstance(registry_payload, dict):
        registry = registry_payload.get("skills")
    else:
        registry = registry_payload
    if not isinstance(registry, list) or len(registry) > 500 or any(not isinstance(item, dict) for item in registry):
        return _error(trace_id, "DESIGN_INVOCATION_SKILL_REGISTRY_INVALID", "승인 Skill registry 입력이 유효하지 않습니다.")
    tenant_id = invocation.get("tenant_id")
    snapshot_id = invocation.get("catalog_snapshot_id")
    design_prompt = invocation.get("design_prompt", "")
    if not _is_identity(tenant_id) or not _is_identity(snapshot_id):
        return _error(trace_id, "DESIGN_INVOCATION_IDENTITY_INVALID", "tenant 또는 active snapshot identity가 유효하지 않습니다.")
    if not isinstance(design_prompt, str) or len(design_prompt) > 20000:
        return _error(trace_id, "DESIGN_INVOCATION_PROMPT_INVALID", "추가 설계 프롬프트가 유효하지 않습니다.")
    try:
        search_seed = _validated_search_seed(invocation.get("search_seed"))
    except ValueError as exc:
        return _error(trace_id, str(exc), "원문 업무 설명 기반 검색 seed가 유효하지 않습니다.")
    if not work or work.get("tenant_id") != tenant_id:
        return _error(trace_id, "DESIGN_INVOCATION_WORK_MISMATCH", "승인 업무 정의와 invocation tenant가 일치하지 않습니다.")
    if not acl or acl.get("subject_id") != work.get("owner_id"):
        return _error(trace_id, "DESIGN_INVOCATION_ACL_MISMATCH", "인증 사용자와 승인 업무 소유자가 일치하지 않습니다.")
    authority = invocation.get("trust_boundary")
    if not isinstance(authority, dict) or authority.get("work_definition_source") != "mongodb-canonical-approved":
        return _error(trace_id, "DESIGN_INVOCATION_AUTHORITY_INVALID", "MongoDB 권위 데이터 재확인 증거가 필요합니다.")
    return {
        "ok": True,
        "status": "READY",
        "schema_version": DESIGN_INVOCATION_SCHEMA_VERSION,
        "tenant_id": str(tenant_id),
        "catalog_snapshot_id": str(snapshot_id),
        "work_definition": copy.deepcopy(work),
        "acl_context": copy.deepcopy(acl),
        "skill_registry": copy.deepcopy(registry),
        "design_prompt": design_prompt,
        "search_seed": copy.deepcopy(search_seed),
        "authority": copy.deepcopy(authority),
        "trace_id": trace_id,
    }


class SearchQueryPlannerComponent(Component):
    display_name = "20 Search Query Planner"
    description = "MongoDB 권위 데이터에서 만든 단일 invocation을 검증하고 검색 query plan으로 변환합니다."
    icon = "ListFilter"
    name = "SearchQueryPlanner"

    inputs = [
        DataInput(name="design_invocation", display_name="Approved Design Invocation", required=True),
        IntInput(name="max_queries", display_name="Maximum Queries", value=30, advanced=True),
    ]
    outputs = [
        Output(
            name="design_scope",
            display_name="Sealed Design Scope",
            method="build_scope",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="query_plan",
            display_name="Search Query Plan",
            method="build_query_plan",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="approved_skill_registry",
            display_name="Approved Skill Registry",
            method="build_skill_registry",
            types=["Data"],
            group_outputs=True,
        ),
    ]

    def _validated_invocation(self) -> dict[str, Any]:
        result = getattr(self, "_invocation_result", None)
        if not isinstance(result, dict):
            result = validate_design_invocation(getattr(self, "design_invocation", None))
            self._invocation_result = result
        return result

    def build_scope(self) -> Data:
        invocation = self._validated_invocation()
        result = invocation if invocation.get("ok") is not True else build_design_scope(
            invocation["work_definition"],
            tenant_id=invocation["tenant_id"],
            catalog_snapshot_id=invocation["catalog_snapshot_id"],
            acl_context=invocation["acl_context"],
            design_prompt=invocation["design_prompt"],
            search_seed=invocation["search_seed"],
        )
        self.status = f"Design scope: {result.get('status')}"
        return Data(data=result)

    def build_query_plan(self) -> Data:
        invocation = self._validated_invocation()
        result = invocation if invocation.get("ok") is not True else build_search_query_plan(
            invocation["work_definition"],
            tenant_id=invocation["tenant_id"],
            catalog_snapshot_id=invocation["catalog_snapshot_id"],
            acl_context=invocation["acl_context"],
            design_prompt=invocation["design_prompt"],
            search_seed=invocation["search_seed"],
            max_queries=getattr(self, "max_queries", 30),
        )
        self.status = f"Query plan: {result.get('status')} / queries={len(result.get('queries', []))}"
        return Data(data=result)

    def build_skill_registry(self) -> Data:
        invocation = self._validated_invocation()
        if invocation.get("ok") is not True:
            return Data(data=copy.deepcopy(invocation))
        return Data(
            data={
                "ok": True,
                "status": "COMPLETED",
                "tenant_id": invocation["tenant_id"],
                "skills": copy.deepcopy(invocation["skill_registry"]),
                "authority": copy.deepcopy(invocation["authority"]),
                "trace_id": invocation["trace_id"],
            }
        )

from __future__ import annotations

"""Create locked query vectors through the connected Langflow Embedding Model."""

import hashlib
import hmac
import json
import math
import re
import time
import uuid
from collections.abc import Callable
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, FloatInput, HandleInput, IntInput, Output
from lfx.schema import Data


_RUNTIME_CONTRACT_SCHEMA = "embedding-runtime-contract/v2"
_MAX_EMBEDDING_DIMENSION = 65536
_MIN_EMBEDDING_CALL_INTERVAL_SECONDS = 1.0
_MAX_EMBEDDING_CALL_INTERVAL_SECONDS = 60.0
_RUNTIME_CLASS_PATTERN = re.compile(
    r"^<class '([A-Za-z_][A-Za-z0-9_]*(?:\.(?:[A-Za-z_][A-Za-z0-9_]*|<locals>))*)'>$"
)
_SAFE_EXCEPTION_TYPE_PATTERN = re.compile(r"^[A-Za-z_][A-Za-z0-9_.]{0,127}$")


def _payload(value: Any, field: str) -> dict[str, Any]:
    data = getattr(value, "data", None)
    value = data if isinstance(data, dict) else value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(f"{field} must be JSON") from exc
    if not isinstance(value, dict):
        raise ValueError(f"{field} must be an object")
    if field == "query_plan" and isinstance(value.get("query_plan"), dict):
        value = value["query_plan"]
    return value


def _canonical_hash(value: Any) -> str:
    material = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def _verified_plan_locks(plan: dict[str, Any]) -> dict[str, str]:
    lock_fields = ("design_scope_sha256", "query_plan_sha256")
    locks = {field: str(plan.get(field) or "") for field in lock_fields}
    if any(not re.fullmatch(r"sha256:[0-9a-fA-F]{64}", value) for value in locks.values()):
        raise ValueError("query plan scope/hash lock is missing or invalid")
    plan_core = {
        key: value
        for key, value in plan.items()
        if key not in {"ok", "status", "query_plan_sha256", "trace_id"}
    }
    if not hmac.compare_digest(locks["query_plan_sha256"].lower(), _canonical_hash(plan_core).lower()):
        raise ValueError("query_plan_sha256 does not match query plan")
    return locks


def _queries(plan: dict[str, Any], maximum: int) -> list[dict[str, str]]:
    raw = plan.get("queries")
    if not isinstance(raw, list) or not raw:
        raise ValueError("query_plan.queries is required")
    if len(raw) > maximum:
        raise ValueError("query count exceeds max_queries")
    result: list[dict[str, str]] = []
    ids: set[str] = set()
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            raise ValueError("each query must be an object")
        query_id = str(item.get("query_id") or item.get("id") or f"query-{index + 1}").strip()[:200]
        text = str(item.get("text") or item.get("query") or "").strip()[:20_000]
        if not query_id or query_id in ids or not text:
            raise ValueError("query IDs must be unique and query text must be present")
        ids.add(query_id)
        result.append({"id": query_id, "text": text})
    return result


def _underlying_embedding(embedding: Any) -> Any:
    if embedding is None:
        raise ValueError("A connected Embedding Model is required")
    try:
        underlying = getattr(embedding, "embeddings", None)
    except Exception:  # noqa: BLE001 - provider wrappers can reject metadata reads
        underlying = None
    return embedding if underlying is None else underlying


def _model_id_text(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    text = value.strip()
    return text if 0 < len(text) <= 500 else ""


def _model_id(embedding: Any, underlying: Any) -> str:
    """Resolve only a provider-selected model identity; never infer from a class name."""
    try:
        available_models = getattr(embedding, "available_models", None)
    except Exception:  # noqa: BLE001 - provider wrappers can reject metadata reads
        available_models = None
    if isinstance(available_models, dict):
        matches = {
            text
            for candidate_id, candidate in available_models.items()
            if candidate is underlying and (text := _model_id_text(candidate_id))
        }
        if len(matches) > 1:
            raise ValueError("Embedding Model identity resolves to more than one configured model ID")
        if matches:
            return next(iter(matches))
    candidates: list[Any] = []
    try:
        candidates.append(getattr(underlying, "model_name", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "model", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "model_id", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "deployment_name", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "deployment", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    for candidate in candidates:
        text = _model_id_text(candidate)
        if text:
            return text
    raise ValueError("The connected Embedding Model does not expose a stable model identity")


def _runtime_class(underlying: Any) -> str:
    rendered = str(type(underlying))
    match = _RUNTIME_CLASS_PATTERN.fullmatch(rendered) if len(rendered) <= 1024 else None
    value = match.group(1) if match else ""
    if not value or len(value) > 1000:
        raise ValueError("The connected Embedding Model does not expose a stable runtime class")
    return value


def _runtime_contract(embedding: Any, dimension: int) -> dict[str, Any]:
    if isinstance(dimension, bool) or not isinstance(dimension, int) or not 1 <= dimension <= _MAX_EMBEDDING_DIMENSION:
        raise ValueError("The embedding response dimension is invalid")
    underlying = _underlying_embedding(embedding)
    contract = {
        "schema_version": _RUNTIME_CONTRACT_SCHEMA,
        "runtime_class": _runtime_class(underlying),
        "model_id": _model_id(embedding, underlying),
        "dimension": dimension,
    }
    return {**contract, "fingerprint": _canonical_hash(contract)}


def _vectors(value: Any, expected_count: int, dimension: int | None, query_ids: list[str]) -> tuple[list[list[float]], int]:
    if not isinstance(value, list) or len(value) != expected_count:
        raise ValueError("The embedding response count does not match the query batch")
    actual_dimension = dimension
    result: list[list[float]] = []
    for index, vector in enumerate(value):
        query_id = query_ids[index]
        if not isinstance(vector, list) or not vector:
            raise ValueError(f"The embedding response vector is missing for query_id={query_id}")
        if actual_dimension is None:
            actual_dimension = len(vector)
            if not 1 <= actual_dimension <= _MAX_EMBEDDING_DIMENSION:
                raise ValueError("The embedding response dimension is invalid")
        if len(vector) != actual_dimension:
            raise ValueError(f"The embedding response vector dimension is invalid for query_id={query_id}")
        normalized: list[float] = []
        for item in vector:
            if isinstance(item, bool):
                raise ValueError(f"The embedding response contains a boolean for query_id={query_id}")
            try:
                number = float(item)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"The embedding response contains a non-numeric value for query_id={query_id}") from exc
            if not math.isfinite(number):
                raise ValueError(f"The embedding response contains a non-finite value for query_id={query_id}")
            normalized.append(number)
        result.append(normalized)
    if actual_dimension is None:
        raise ValueError("The embedding response did not contain a vector dimension")
    return result, actual_dimension


class _ProviderEmbeddingError(RuntimeError):
    """A provider failure with a safe, non-secret diagnostic summary.

    Provider exception strings can include request URLs, credential hints, or
    other operational details.  Keep the exception chained for local traces,
    but expose only its class, an HTTP status when available, and a coarse
    category to Langflow users.
    """

    pass


def _safe_exception_type(cause: Exception) -> str:
    # Standalone components intentionally avoid introspection such as
    # ``__module__``.  A bounded class name is enough for operator diagnostics.
    value = type(cause).__name__
    return value if _SAFE_EXCEPTION_TYPE_PATTERN.fullmatch(value) else "provider_exception"


def _provider_http_status(cause: Exception) -> int | None:
    """Read a status field without copying an arbitrary provider message."""
    try:
        response = cause.response
    except Exception:  # noqa: BLE001 - third-party error objects can use arbitrary properties
        response = None
    candidates: list[Any] = []
    for target in (cause, response):
        if target is None:
            continue
        try:
            candidates.append(target.status_code)
        except Exception:  # noqa: BLE001 - third-party error objects can use arbitrary properties
            pass
        try:
            candidates.append(target.status)
        except Exception:  # noqa: BLE001 - third-party error objects can use arbitrary properties
            pass
    for value in candidates:
        if isinstance(value, bool):
            continue
        if isinstance(value, int) and 100 <= value <= 599:
            return value
    return None


def _provider_error_category(cause: Exception, http_status: int | None) -> str:
    """Classify known transient/configuration families without emitting raw text."""
    try:
        material = str(cause).casefold()
    except Exception:  # noqa: BLE001 - defensive only; do not surface provider text
        material = ""
    if http_status in {401, 403} or any(token in material for token in ("api key", "credential", "unauthenticated", "permission denied")):
        return "authentication_or_authorization"
    if http_status == 429 or any(token in material for token in ("quota", "rate limit", "resource exhausted", "too many requests")):
        return "rate_limited_or_quota"
    if http_status is not None and 400 <= http_status < 500:
        return "provider_request_rejected"
    if http_status is not None and http_status >= 500:
        return "provider_temporary_failure"
    if any(token in material for token in ("timeout", "temporarily", "connection", "unavailable", "network")):
        return "provider_temporary_failure"
    return "provider_runtime_failure"


def _provider_embedding_error(cause: Exception) -> _ProviderEmbeddingError:
    """Build a marker error whose ordinary args contain only safe diagnostics."""
    http_status = _provider_http_status(cause)
    return _ProviderEmbeddingError(
        _safe_exception_type(cause),
        http_status,
        _provider_error_category(cause, http_status),
    )


def _provider_embedding_error_summary(error: _ProviderEmbeddingError) -> tuple[str, int | None, str]:
    args = error.args if isinstance(error.args, tuple) else ()
    exception_type = args[0] if len(args) >= 1 and isinstance(args[0], str) else "provider_exception"
    http_status = args[1] if len(args) >= 2 and isinstance(args[1], int) and not isinstance(args[1], bool) else None
    category = args[2] if len(args) >= 3 and isinstance(args[2], str) else "provider_runtime_failure"
    if not _SAFE_EXCEPTION_TYPE_PATTERN.fullmatch(exception_type):
        exception_type = "provider_exception"
    if category not in {
        "authentication_or_authorization",
        "rate_limited_or_quota",
        "provider_request_rejected",
        "provider_temporary_failure",
        "provider_runtime_failure",
    }:
        category = "provider_runtime_failure"
    return exception_type, http_status, category


def _embed_documents(embedding: Any, texts: list[str], query_ids: list[str], dimension: int | None) -> tuple[list[list[float]], int]:
    try:
        method = getattr(embedding, "embed_documents", None)
    except Exception as exc:  # noqa: BLE001 - provider wrappers can expose arbitrary properties
        raise ValueError("The connected Embedding Model could not be used") from exc
    if not callable(method):
        raise ValueError("The connected Embedding Model does not provide embed_documents")
    try:
        raw_vectors = method(texts)
    except Exception as exc:  # noqa: BLE001 - providers expose heterogeneous error types
        raise _provider_embedding_error(exc) from exc
    return _vectors(raw_vectors, len(texts), dimension, query_ids)


def _query_embedding_method(embedding: Any, underlying: Any) -> Callable[[str], Any] | None:
    """Prefer the provider's query-specific API without requiring one from every adapter."""
    for candidate in (embedding, underlying):
        try:
            method = getattr(candidate, "embed_query", None)
        except Exception:  # noqa: BLE001 - provider wrappers can expose arbitrary properties
            continue
        if callable(method):
            return method
    return None


def _embed_query(
    method: Callable[[str], Any],
    text: str,
    query_id: str,
    dimension: int | None,
) -> tuple[list[list[float]], int]:
    """Embed exactly one retrieval query and normalize the one-vector contract."""
    try:
        raw_vector = method(text)
    except Exception as exc:  # noqa: BLE001 - providers expose heterogeneous error types
        raise _provider_embedding_error(exc) from exc
    # A few adapters wrap the single vector once more.  That shape is
    # unambiguous for an exactly-one query call and is safe to normalize.
    if isinstance(raw_vector, list) and len(raw_vector) == 1 and isinstance(raw_vector[0], list):
        raw_vector = raw_vector[0]
    return _vectors([raw_vector], 1, dimension, [query_id])


def _run_embedding_call_with_retries(
    action: Callable[[], tuple[list[list[float]], int]],
    *,
    interval_seconds: float,
    max_retries: int,
    is_first_provider_call: bool,
) -> tuple[list[list[float]], int, int, int]:
    """Run one logical embedding action with the shared provider rate floor."""
    retries = 0
    while True:
        if not is_first_provider_call or retries:
            time.sleep(interval_seconds)
        try:
            vectors, dimension = action()
            return vectors, dimension, retries + 1, retries
        except _ProviderEmbeddingError:
            if retries >= max_retries:
                raise
            retries += 1


def _bounded_interval(value: Any) -> float:
    """Return the shared 1-second floor used by catalog and query embedding.

    The catalog ingest flow deliberately serializes one provider call at a
    time because the approved embedding service can reject rapid requests.
    Search-query embedding has the same provider boundary, so it must not
    bypass that protection simply because it has fewer texts.
    """
    try:
        interval = float(value)
    except (TypeError, ValueError):
        interval = _MIN_EMBEDDING_CALL_INTERVAL_SECONDS
    if not math.isfinite(interval):
        interval = _MIN_EMBEDDING_CALL_INTERVAL_SECONDS
    return max(_MIN_EMBEDDING_CALL_INTERVAL_SECONDS, min(_MAX_EMBEDDING_CALL_INTERVAL_SECONDS, interval))


def _error(
    trace_id: str,
    code: str,
    message: str,
    *,
    retryable: bool = False,
    details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
    }


def _configuration_error(trace_id: str, exc: Exception) -> dict[str, Any]:
    """Convert expected provider/model faults to an actionable safe envelope.

    The raw provider exception may contain endpoint details or credentials, so
    it is intentionally not surfaced in the Flow result.  The explicit action
    list is enough for a Langflow operator to fix a model binding.
    """
    text = str(exc)
    model_markers = (
        "Embedding Model",
        "stable model identity",
        "runtime class",
        "embed_documents",
        "more than one configured model",
    )
    vector_markers = (
        "embedding response",
        "vector is missing",
        "dimension is invalid",
        "boolean",
        "non-numeric",
        "non-finite",
    )
    if any(marker in text for marker in model_markers):
        return _error(
            trace_id,
            "EMBEDDING_MODEL_CONFIGURATION_REQUIRED",
            "승인 카탈로그와 같은 Langflow Embedding Model을 연결하고, provider가 안정적인 모델 ID와 embed_query 또는 embed_documents를 제공하는지 확인하세요.",
            details={
                "next_actions": [
                    "F00에 사용한 동일 provider/model을 Search Query Embedding Batcher에 연결합니다.",
                    "Embedding Model의 API credential과 모델 선택을 확인합니다.",
                ]
            },
        )
    if any(marker in text for marker in vector_markers):
        return _error(
            trace_id,
            "EMBEDDING_RESPONSE_INVALID",
            "Embedding Model 응답이 검색 query 수 또는 vector 차원 계약과 일치하지 않습니다.",
            details={"next_actions": ["Embedding provider의 batch 응답 수와 vector dimension을 확인합니다."]},
        )
    return _error(
        trace_id,
        "QUERY_EMBEDDING_INPUT_INVALID",
        "검색 query plan 또는 embedding 실행 설정이 유효하지 않습니다.",
        details={"next_actions": ["F20/F90의 sealed design invocation과 query 수 제한을 확인합니다."]},
    )


class SearchQueryEmbeddingBatcherComponent(Component):
    display_name = "29 Search Query Embedding Batcher"
    description = "Vectorize locked search queries through the connected Langflow Embedding Model in bounded batches, with at least one second between provider calls."
    icon = "Binary"
    name = "SearchQueryEmbeddingBatcher"

    inputs = [
        DataInput(name="query_plan", display_name="Search Query Plan", required=True),
        HandleInput(name="embedding", display_name="Embedding Model", input_types=["Embeddings"], required=True),
        IntInput(name="batch_size", display_name="Embedding Batch Size", value=16, advanced=True),
        IntInput(name="max_queries", display_name="Maximum Queries", value=30, advanced=True),
        IntInput(
            name="max_embedding_retries",
            display_name="Maximum Embedding Retries",
            value=2,
            advanced=True,
            info="Retries only transient provider failures. Each retry also waits at least the configured call interval.",
        ),
        FloatInput(
            name="embedding_call_interval_seconds",
            display_name="Embedding Call Interval (seconds)",
            value=_MIN_EMBEDDING_CALL_INTERVAL_SECONDS,
            advanced=True,
            info="The first provider call starts immediately. Later batches wait at least 1 second; values below 1 are raised to 1.",
        ),
    ]
    outputs = [Output(name="query_vectors", display_name="ID-preserving Query Vectors", method="build_query_vectors", types=["Data"])]

    def build_query_vectors(self) -> Data:
        trace_id = str(uuid.uuid4())
        try:
            plan = _payload(getattr(self, "query_plan", None), "query_plan")
            locks = _verified_plan_locks(plan)
            maximum = max(1, min(int(getattr(self, "max_queries", 30) or 30), 100))
            queries = _queries(plan, maximum)
            embedding = getattr(self, "embedding", None)
            underlying = _underlying_embedding(embedding)
            # Resolve model metadata before the first provider request so unknown model
            # identities fail closed without creating an untraceable vector snapshot.
            _model_id(embedding, underlying)
            _runtime_class(underlying)
            batch_size = max(1, min(int(getattr(self, "batch_size", 16) or 16), 128))
            interval = _bounded_interval(
                getattr(self, "embedding_call_interval_seconds", _MIN_EMBEDDING_CALL_INTERVAL_SECONDS)
            )
            max_retries = max(0, min(int(getattr(self, "max_embedding_retries", 2) or 0), 4))
            vectors: dict[str, list[float]] = {}
            dimension: int | None = None
            call_count = 0
            retry_count = 0
            query_method = _query_embedding_method(embedding, underlying)
            if query_method is not None:
                # Query-specific APIs such as Google Gemini's embed_query use a
                # RETRIEVAL_QUERY task type.  This is semantically correct for
                # F20's search terms and avoids treating a query as catalog text.
                for item in queries:
                    batch_vectors, dimension, calls, retries = _run_embedding_call_with_retries(
                        lambda item=item, dimension=dimension: _embed_query(
                            query_method,
                            item["text"],
                            item["id"],
                            dimension,
                        ),
                        interval_seconds=interval,
                        max_retries=max_retries,
                        is_first_provider_call=call_count == 0,
                    )
                    call_count += calls
                    retry_count += retries
                    vectors[item["id"]] = batch_vectors[0]
            else:
                # Not every Langflow Embeddings adapter exposes embed_query.
                # Keep the sealed batch contract as a compatible fallback.
                for start in range(0, len(queries), batch_size):
                    batch = queries[start : start + batch_size]
                    batch_vectors, dimension, calls, retries = _run_embedding_call_with_retries(
                        lambda batch=batch, dimension=dimension: _embed_documents(
                            embedding,
                            [item["text"] for item in batch],
                            [item["id"] for item in batch],
                            dimension,
                        ),
                        interval_seconds=interval,
                        max_retries=max_retries,
                        is_first_provider_call=call_count == 0,
                    )
                    call_count += calls
                    retry_count += retries
                    for item, vector in zip(batch, batch_vectors):
                        vectors[item["id"]] = vector
            contract = _runtime_contract(embedding, dimension if dimension is not None else 0)
            result = {
                "ok": True,
                "status": "VECTORIZED",
                "schema_version": "query-vectors/v1",
                "vectors": vectors,
                "query_order": [item["id"] for item in queries],
                "embedding_contract": contract,
                "embedding_execution": {
                    "calls": call_count,
                    "retry_attempts": retry_count,
                    "minimum_interval_seconds": interval,
                    "batch_size": batch_size,
                },
                **locks,
                "trace_id": trace_id,
            }
            self.status = (
                f"Vectorized {len(vectors)} queries with {contract['model_id']} ({contract['dimension']}d); "
                f"{call_count} provider calls at >= {interval:.1f}s intervals."
            )
            return Data(data=result)
        except _ProviderEmbeddingError as exc:
            exception_type, http_status, category = _provider_embedding_error_summary(exc)
            retryable = category not in {"authentication_or_authorization", "provider_request_rejected"}
            details: dict[str, Any] = {
                "provider_failure_category": category,
                "provider_exception_type": exception_type,
                "next_actions": [
                    "F00과 같은 Embedding Model의 credential, provider 상태, quota를 확인합니다.",
                    "일시 장애 또는 quota 제한이면 잠시 후 같은 F20 입력으로 다시 실행합니다.",
                ],
            }
            if http_status is not None:
                details["provider_http_status"] = http_status
            result = _error(
                trace_id,
                "EMBEDDING_PROVIDER_ERROR",
                "Embedding Model이 검색 query를 벡터화하지 못했습니다. provider 상태와 credential을 확인한 뒤 다시 실행하세요.",
                retryable=retryable,
                details=details,
            )
        except (TypeError, ValueError) as exc:
            result = _configuration_error(trace_id, exc)
        self.status = f"Query embedding blocked: {result['error']['code']}"
        return Data(data=result)

